@push('scripts')
<script>
(()=>{new DataTable('#setupTable',{pageLength:15,lengthMenu:[10,15,25,50,100],order:[[1,'asc']],columnDefs:[{targets:[3,4,5,6],className:'text-end'}]});const products=@json($products),modal=bootstrap.Modal.getOrCreateInstance(document.getElementById('setupModal')),msg=bootstrap.Modal.getOrCreateInstance(document.getElementById('msgModal'));const show=(t,m)=>{const c={success:['Berhasil','✓','bg-success text-white'],danger:['Gagal','✕','bg-danger text-white'],warning:['Peringatan','!','bg-warning text-dark']}[t];msgHeader.className='modal-header '+c[2];msgTitle.textContent=c[1]+' '+c[0];msgBody.textContent=m;msg.show()},dec=v=>Number(String(v??'').replace(',','.').replace(/[^0-9.-]/g,''))||0,fmt=v=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(dec(v));ssearch.oninput=()=>{sid.value='';draw()};ssearch.onfocus=draw;ssearch.onblur=()=>setTimeout(()=>popup.style.display='none',150);function draw(){const q=ssearch.value.toLowerCase().trim(),rs=products.filter(p=>!q||[p.name,p.code,p.barcode].some(v=>String(v||'').toLowerCase().includes(q))).slice(0,30);popup.innerHTML=rs.length?rs.map((p,i)=>'<button type="button" class="list-group-item list-group-item-action text-start" data-i="'+i+'"><b>'+p.name+'</b><div class="small text-secondary">'+p.code+(p.barcode?' · '+p.barcode:'')+(p.unit_code?' · '+p.unit_code:'')+'</div></button>').join(''):'<div class="list-group-item text-secondary">Barang tidak ditemukan.</div>';popup.style.display='block';popup.querySelectorAll('[data-i]').forEach(b=>b.onmousedown=e=>{e.preventDefault();const p=rs[+b.dataset.i];sid.value=p.id;ssearch.value=p.name;popup.style.display='none'})}scost.oninput=()=>{const c=dec(scost.value),m=dec(smarkup.value);if(c)sprice.value=fmt(c*(1+m/100))};smarkup.oninput=scost.oninput;sprice.oninput=()=>{const c=dec(scost.value),p=dec(sprice.value);smarkup.value=c?((p-c)/c*100).toFixed(2):'0'};setupForm.onsubmit=async e=>{e.preventDefault();saveSetup.disabled=true;try{const r=await fetch('{{route('inventori.setup-stok-harga.store')}}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content,'Accept':'application/json'},body:new URLSearchParams({setup_date:sdate.value,product_id:sid.value,initial_stock:dec(sstock.value),purchase_price:dec(scost.value),markup_percent:dec(smarkup.value),selling_price:dec(sprice.value)})}),j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.message||'Setup gagal disimpan.');modal.hide();show('success',j.message);setTimeout(()=>location.reload(),300)}catch(e){show('danger',e.message)}finally{saveSetup.disabled=false}}})();
</script>
